// Keyword finder: longest patterns first, so "dual carriageway" wins over "carriageway"
const KW_LIST = [];
WORDS.forEach(w => w.m.forEach(p => KW_LIST.push({ id: w.id, p: p })));
KW_LIST.sort((a, b) => b.p.length - a.p.length);
const KW_RE = new RegExp("(?<![A-Za-z0-9-])(?:" + KW_LIST.map(k => k.p).join("|") + ")(?![A-Za-z0-9-])", "gi");
const KW_TEST = KW_LIST.map(k => ({ id: k.id, re: new RegExp("^(?:" + k.p + ")$", "i") }));
const WORD_BY_ID = {};
WORDS.forEach(w => { WORD_BY_ID[w.id] = w; });
const kwId = (txt) => { for (const k of KW_TEST) if (k.re.test(txt)) return k.id; return null; };
